    def max_sum_sq(n, S):
        max_val = -1
        for k in range(n + 1):
            for m in range(n - k + 1):
                d = k - m
                x_j = S - d
                if -1 <= x_j <= 1:
                    max_val = max(max_val, k + m + x_j**2)
        return max_val

